const d = $input.first().json;
const nombre = d.nombre_cliente || 'cliente';
const pedido = d.numero_pedido || '';
const texto = `Hola ${nombre}! 😊 Han pasado 24h desde que recibiste tu pedido ${pedido}. ¿Todo llegó perfectamente? ¿Estás contento con tu compra? Nos encantaría saberlo. ¡Gracias por confiar en Noxertez! 🪵`;
return [{ json: {
  numero_pedido: pedido,
  telefono: d.telefono || '',
  nombre_cliente: nombre,
  texto_mensaje: texto,
  timestamp: new Date().toISOString()
}}];
